from codemind.agent.security import SecurityService


class OutputGuardrails:
    """Validate and sanitize responses generated by the agent."""

    def __init__(self, security: SecurityService | None = None):
        self.security = security or SecurityService()

    def validate(self, answer: str) -> str:
        """Validate an answer and redact any likely secrets."""

        if not isinstance(answer, str):
            raise ValueError(  # noqa: TRY004
                "Agent answer must be a string"
            )

        if not answer.strip():
            raise ValueError("Agent answer cannot be empty")

        result = self.security.scan_untrusted_content(answer)

        return result.sanitized_text
